import io, contextlib
stdout_capture = io.StringIO()
local_vars = {}
try:
    with contextlib.redirect_stdout(stdout_capture):
        exec(code, {}, local_vars)
    output = stdout_capture.getvalue()
    result = {'output': output, 'variables': {k: str(v)[:200] for k, v in local_vars.items() if not k.startswith('_')}, 'result': str(local_vars.get('result', output or '(no output)'))[:2000]}
except Exception as e:
    result = {'error': str(e)}
